package sprint

import (
	"encoding/json"
	"errors"
	"fmt"
	"io/fs"
	"os"
	"path/filepath"
	"syscall"
	"time"
)

type verificationLockInfo struct {
	Project    string    `json:"project"`
	Sprint     string    `json:"sprint"`
	PID        int       `json:"pid"`
	AcquiredAt time.Time `json:"acquiredAt"`
}

type verificationFileLock struct {
	path string
	info verificationLockInfo
}

func acquireVerificationFileLock(root string, sprint Sprint, now time.Time) (*verificationFileLock, error) {
	path := filepath.Join(root, ".ultraplan", "locks", "sprint", sprint.Project+"--"+sprint.Slug+".lock")
	if err := os.MkdirAll(filepath.Dir(path), 0o755); err != nil {
		return nil, fmt.Errorf("create verification lock directory: %w", err)
	}
	info := verificationLockInfo{Project: sprint.Project, Sprint: sprint.Slug, PID: os.Getpid(), AcquiredAt: now.UTC()}
	for attempt := 0; attempt < 2; attempt++ {
		file, err := os.OpenFile(path, os.O_WRONLY|os.O_CREATE|os.O_EXCL, 0o644)
		if err == nil {
			data, marshalErr := json.Marshal(info)
			if marshalErr == nil {
				_, marshalErr = file.Write(append(data, '\n'))
			}
			closeErr := file.Close()
			if marshalErr != nil || closeErr != nil {
				_ = os.Remove(path)
				return nil, errors.Join(marshalErr, closeErr)
			}
			return &verificationFileLock{path: path, info: info}, nil
		}
		if !errors.Is(err, fs.ErrExist) {
			return nil, fmt.Errorf("create verification lock: %w", err)
		}
		existing, readErr := readVerificationFileLock(path)
		if readErr != nil {
			return nil, fmt.Errorf("%w: unreadable lock %s: %v", ErrVerificationConflict, path, readErr)
		}
		if verificationProcessAlive(existing.PID) {
			return nil, fmt.Errorf("%w for %s/%s; pid %d has owned the attempt since %s", ErrVerificationConflict, sprint.Project, sprint.Slug, existing.PID, existing.AcquiredAt.Format(time.RFC3339))
		}
		if removeErr := os.Remove(path); removeErr != nil && !errors.Is(removeErr, fs.ErrNotExist) {
			return nil, fmt.Errorf("remove stale verification lock: %w", removeErr)
		}
	}
	return nil, fmt.Errorf("%w for %s/%s", ErrVerificationConflict, sprint.Project, sprint.Slug)
}

func readVerificationFileLock(path string) (verificationLockInfo, error) {
	data, err := os.ReadFile(path)
	if err != nil {
		return verificationLockInfo{}, err
	}
	var info verificationLockInfo
	if err := json.Unmarshal(data, &info); err != nil {
		return verificationLockInfo{}, err
	}
	if info.PID <= 0 || info.Project == "" || info.Sprint == "" || info.AcquiredAt.IsZero() {
		return verificationLockInfo{}, fmt.Errorf("invalid lock identity")
	}
	return info, nil
}

func (lock *verificationFileLock) release() error {
	if lock == nil {
		return nil
	}
	current, err := readVerificationFileLock(lock.path)
	if errors.Is(err, fs.ErrNotExist) {
		return nil
	}
	if err != nil {
		return err
	}
	if current.PID != lock.info.PID || current.Project != lock.info.Project || current.Sprint != lock.info.Sprint || !current.AcquiredAt.Equal(lock.info.AcquiredAt) {
		return fmt.Errorf("verification lock ownership changed; refusing release")
	}
	return os.Remove(lock.path)
}

func verificationProcessAlive(pid int) bool {
	if pid <= 0 {
		return false
	}
	err := syscall.Kill(pid, 0)
	return err == nil || errors.Is(err, syscall.EPERM)
}

package sprint

import (
	"context"
	"encoding/json"
	"errors"
	"fmt"
	"io/fs"
	"os"
	"path/filepath"
	"strings"
	"time"
)

const cleanupUncertainFileName = ".cleanup-uncertain.json"

var ErrCleanupUncertain = errors.New("sprint cleanup remains uncertain")

type CleanupUncertainRecord struct {
	SchemaVersion int       `json:"schemaVersion"`
	OperationID   string    `json:"operationId"`
	Kind          string    `json:"kind"`
	Reason        string    `json:"reason"`
	OwnerPID      int       `json:"ownerPid"`
	RecordedAt    time.Time `json:"recordedAt"`
}

// RecordCleanupUncertain writes a separate product-owned recovery marker. It
// deliberately does not rewrite canonical run state or acquire the mutation
// lease: at deadline exhaustion the original owner may still hold that lease.
func (s Service) RecordCleanupUncertain(ctx context.Context, projectRef, sprintRef string, record CleanupUncertainRecord) error {
	if err := ctx.Err(); err != nil {
		return err
	}
	sp, err := s.resolveMutationSprint(projectRef, sprintRef)
	if err != nil {
		return err
	}
	record.SchemaVersion = 1
	record.OperationID = strings.TrimSpace(record.OperationID)
	record.Kind = strings.TrimSpace(record.Kind)
	record.Reason = strings.TrimSpace(record.Reason)
	record.OwnerPID = os.Getpid()
	if record.RecordedAt.IsZero() {
		record.RecordedAt = s.now().UTC()
	} else {
		record.RecordedAt = record.RecordedAt.UTC()
	}
	if record.OperationID == "" || record.Kind == "" || record.Reason != "server_shutdown" || strings.ContainsAny(record.OperationID+record.Kind, "\x00\r\n") {
		return fmt.Errorf("invalid cleanup uncertainty record")
	}
	data, err := json.MarshalIndent(record, "", "  ")
	if err != nil {
		return err
	}
	data = append(data, '\n')
	return atomicWriteFile(filepath.Join(sp.Path, cleanupUncertainFileName), data)
}

func loadCleanupUncertain(sp Sprint) (CleanupUncertainRecord, error) {
	path := filepath.Join(sp.Path, cleanupUncertainFileName)
	data, err := os.ReadFile(path)
	if err != nil {
		return CleanupUncertainRecord{}, err
	}
	var record CleanupUncertainRecord
	if err := json.Unmarshal(data, &record); err != nil {
		return CleanupUncertainRecord{}, fmt.Errorf("read cleanup uncertainty %s: %w", path, err)
	}
	if record.SchemaVersion != 1 || record.OperationID == "" || record.Kind == "" || record.Reason != "server_shutdown" || record.OwnerPID < 1 || record.RecordedAt.IsZero() {
		return CleanupUncertainRecord{}, fmt.Errorf("invalid cleanup uncertainty record %s", path)
	}
	return record, nil
}

func removeCleanupUncertain(sp Sprint) error {
	err := os.Remove(filepath.Join(sp.Path, cleanupUncertainFileName))
	if errors.Is(err, fs.ErrNotExist) {
		return nil
	}
	return err
}

package sprint

import (
	"context"
	"errors"
	"fmt"
	"os"
	"path/filepath"

	"github.com/Antonio7098/ultraplan-go/internal/project"
)

// The mutation lease is product-owned and shared by flow, execute, review,
// smoke, and verify. A context marker permits composite workflows to invoke
// child stages without reacquiring the same cross-process file lock.
type mutationLeaseContextKey struct{}

type mutationLeaseContext struct {
	path string
}

// ReconcileInterruptedMutation converts durable running records left by a
// dead owner into explicit interrupted evidence. A live cross-process lease is
// never rewritten.
func (s Service) ReconcileInterruptedMutation(ctx context.Context, projectRef, sprintRef string) (bool, error) {
	lockedCtx, release, err := s.acquireMutationContext(ctx, projectRef, sprintRef)
	if err != nil {
		if errors.Is(err, ErrVerificationConflict) {
			return false, nil
		}
		return false, err
	}
	defer release()
	_ = lockedCtx
	sp, err := s.resolveMutationSprint(projectRef, sprintRef)
	if err != nil {
		return false, err
	}
	now := s.now().UTC()
	_, uncertaintyErr := loadCleanupUncertain(sp)
	hasUncertainty := uncertaintyErr == nil
	if uncertaintyErr != nil && !errors.Is(uncertaintyErr, os.ErrNotExist) {
		return false, uncertaintyErr
	}
	changed := false
	state, err := LoadExecuteRunState(s.root, sp)
	if err == nil {
		for i := range state.Tasks {
			if state.Tasks[i].Status != ExecuteTaskRunning {
				continue
			}
			state.Tasks[i].Status = ExecuteTaskFailed
			state.Tasks[i].UpdatedAt = now
			state.Tasks[i].CompletedAt = &now
			state.Tasks[i].Diagnostics = append(state.Tasks[i].Diagnostics, ExecuteDiagnostic{Code: "recovery-interrupted", Message: "running task belonged to a stopped process; inspect durable target state before resuming", At: now})
			changed = true
		}
		if changed {
			state.UpdatedAt = now
			if err := SaveExecuteRunState(s.root, sp, state); err != nil {
				return false, err
			}
		}
	} else if !errors.Is(err, ErrExecuteRunStateMissing) && !legacyTerminalExecuteRunState(s.root, sp) {
		return false, err
	}
	flow, flowErr := LoadFlowState(s.root, sp)
	if flowErr == nil {
		if reconcileExpiredAttempts(&flow, now) {
			flow.UpdatedAt = now
			if err := SaveFlowState(s.root, sp, flow); err != nil {
				return false, err
			}
			changed = true
		}
		qaStore := NewQAStore(s.root, sp)
		if qaPath, pathErr := qaStore.StatePath(); pathErr == nil {
			if _, statErr := os.Lstat(qaPath); statErr == nil {
				qaState, qaErr := qaStore.LoadState()
				if qaErr != nil {
					return false, qaErr
				}
				switch qaState.Phase {
				case QAPhaseQueued, QAPhaseRunning, QAPhaseSynthesizing:
					qaState.Phase = QAPhaseInterrupted
					qaState.Run.Lifecycle = QARunTerminal
					qaState.Run.TerminalResult = QATerminalInterrupted
					qaState.Blocker = &QABlocker{Category: QAErrorConflict, Scope: "attempt", Summary: "the prior QA owner stopped before recording a terminal result", NextAction: "Run qa recover, then qa resume with a new durable owner."}
					qaState.NextAction = qaState.Blocker.NextAction
					qaState.UpdatedAt = now
					if err := qaStore.SaveRecoveredState(qaState, flow); err != nil {
						return false, err
					}
					changed = true
				}
			}
		}
	} else if !errors.Is(flowErr, ErrFlowStateMissing) && !legacyFlowState(s.root, sp) {
		return false, flowErr
	}
	if hasUncertainty && changed {
		if err := removeCleanupUncertain(sp); err != nil {
			return false, err
		}
	}
	if hasUncertainty && !changed {
		return false, fmt.Errorf("%w: %s", ErrCleanupUncertain, filepath.Join(sp.Path, cleanupUncertainFileName))
	}
	return changed, nil
}

func (s Service) acquireMutationContext(ctx context.Context, projectRef, sprintRef string) (context.Context, func(), error) {
	sp, err := s.resolveMutationSprint(projectRef, sprintRef)
	if err != nil {
		return ctx, nil, err
	}
	path := filepath.Clean(sp.Path)
	if held, ok := ctx.Value(mutationLeaseContextKey{}).(mutationLeaseContext); ok && held.path == path {
		return ctx, func() {}, nil
	}
	release, err := s.acquireMutation(projectRef, sprintRef)
	if err != nil {
		return ctx, nil, err
	}
	return context.WithValue(ctx, mutationLeaseContextKey{}, mutationLeaseContext{path: path}), release, nil
}

func (s Service) resolveMutationSprint(projectRef, sprintRef string) (Sprint, error) {
	projects, err := project.DiscoverProjects(s.root)
	if err != nil {
		return Sprint{}, err
	}
	p, err := project.ResolveProject(projects, projectRef)
	if err != nil {
		return Sprint{}, err
	}
	sprints, err := DiscoverSprints(s.root, p)
	if err != nil {
		return Sprint{}, err
	}
	sp, err := ResolveSprint(sprints, sprintRef)
	return sp, err
}

